import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import { LEGACY_CATEGORY_PRESETS, buildLegacyFormatOptions } from "@huau/core";
import type { LegacyFormatOption, LegacySeedingMethod } from "@huau/core";
import type { Locale } from "./i18n";
import { TeamCompetitionPanel, TeamResultsPanel, TeamTVPanel, TeamTournamentPanel } from "./TeamTournamentPanel";
import { TournamentRegistrationAdmin } from "./TournamentRegistration";

type Props = { organizationId: string; tournamentId: string; locale: Locale; go: (path: string) => void };
type Tab = "overview"|"players"|"categories"|"registrations"|"teams"|"format"|"draw"|"competition"|"schedule"|"results"|"tv"|"settings"|"recovery";
type Settings = {
  club:string;city:string;location:string;description:string;contact:string;dailyStart:string;dailyEnd:string;defaultMatchMinutes:number;
  paymentType:"per_category"|"base_plus_extra"|"free";entryFeeMinor:number|null;baseFeeMinor:number|null;extraCategoryFeeMinor:number|null;registrationCloseAt:number|null;
  minimumGroup:number;preferredGroup:number;maximumGroup:number;suggestedQualifiersPerGroup:number;seedingMethod:LegacySeedingMethod;minimumRestSlots:number;
};
type Category = {id:string;name:string;entryType:"individual"|"pair"|"team";competitionGender:string|null;minAge:number|null;maxAge:number|null;maxEntries:number|null;registrationStatus:"closed"|"open"|"waitlist_only";priceScope:"free"|"per_entry"|"per_person";priceMinor:number|null;currency:string|null;scheduledDate:string|null;sortOrder:number;structureLocked:number;formatVersionId:string|null;entryCount:number;competitionStatus:string|null;groupMatchCount:number;finishedGroupMatchCount:number;finalMatchCount:number;configJson:string|null};
type Entry = {id:string;categoryId:string;displayName:string;entryType:string;status:string;seedRating:number;sourceKind?:string|null;sourceKey?:string|null;members:string|null};
type Player = {id:string;displayName:string;club:string;contact:string;sportGender:"male"|"female"|"unspecified";duprSingles:number;duprDoubles:number;paymentStatus:"pending"|"paid";playerStatus:"pending"|"confirmed";notes:string;sortOrder:number};
type Assignment = {playerProfileId:string;categoryId:string;partnerProfileId:string|null};
type GroupRow = {id:string;name:string;categoryId:string;entryId:string|null;entryName:string|null;sortOrder:number|null;seed?:number|null};
type Match = {encounterId:string;categoryId:string;categoryName:string;stage:string;groupId:string|null;groupName:string|null;roundLabel:string|null;roundNumber?:number|null;legNumber:number;entryAId:string|null;sideA:string|null;entryBId:string|null;sideB:string|null;status:string;winnerEntryId:string|null;matchId:string|null;bestOf:number;pointTarget:number|null;scoreA:number|null;scoreB:number|null;resultStatus:string|null;scheduleStart?:number|null;scheduleEnd?:number|null;courtLabel?:string|null;sets?:Array<{setNumber:number;scoreA:number;scoreB:number;winnerSide:string}>};
type ScheduleRow = {id:string;categoryId:string;categoryName:string;categoryEntryType:"individual"|"pair"|"team";encounterId:string|null;matchId:string|null;stage:string;roundLabel:string|null;courtLabel:string;startAt:number;endAt:number;status:string;groupId:string|null;groupName:string|null;legNumber:number|null;entryAId:string|null;sideA:string|null;entryBId:string|null;sideB:string|null;rubberKey:string|null;rubberOrder:number|null;matchMode:string|null;matchGender:string|null;bestOf:number|null};
type Standing = {categoryId:string;groupId:string;groupName:string;rows:Array<{position:number;entryId:string;name:string;played:number;wins:number;losses:number;scored:number;conceded:number;diff:number;rating:number}>};
type CrossRow = {categoryId:string;groupId:string;groupName:string;position:number;entryId:string;name:string;played:number;wins:number;winRate:number;diff:number;diffPerMatch:number;scored:number;scoredPerMatch:number;method:string;ignoredEncounterIds:string[]};
type DrawSession = {categoryId:string;status:string;stateJson:string;updatedAt:number};
type LiveDrawState = {entryOrder:string[];assignments:Record<string,string[]>;revealIndex:number;lastEntryId:string|null;lastGroup:string|null;status:string};
type LiveDrawResponse = {ok:true;state:LiveDrawState};
type Snapshot = {id:string;scopeType:string;scopeId:string|null;reason:string;revision:number;createdAt:number;categoryName:string|null};
type RefreshMode = "background"|"blocking"|"none";
type ActionRunner = <T=unknown>(fn:()=>Promise<T>, afterMutation?:(result:T)=>void, refreshMode?:RefreshMode)=>Promise<T|undefined>;

type Detail = {
  tournament:{id:string;name:string;slug:string;sport:string;status:string;visibility:string;startAt:number;endAt:number|null;timezone:string;courtCount:number;publicParticipants:number;publicLive:number;structureLocked:number;publishedRevision:number;workingRevision:number};
  settings:Settings;categories:Category[];entries:Entry[];players:Player[];playerCategories:Assignment[];groups:GroupRow[];matches:Match[];schedule:ScheduleRow[];standings:Standing[];crossGroup:CrossRow[];drawSessions:DrawSession[];snapshots:Snapshot[];
};

class ApiError extends Error { code:string; impact:string|undefined; constructor(code:string,impact?:string){super(code);this.code=code;this.impact=impact;} }
const text=(locale:Locale,es:string,en:string)=>locale==="es"?es:en;
const toMs=(value:number)=>value<10_000_000_000?value*1000:value;
const date=(value:number)=>new Intl.DateTimeFormat("es-UY",{dateStyle:"medium"}).format(new Date(toMs(value)));
const dt=(value:number)=>new Intl.DateTimeFormat("es-UY",{dateStyle:"short",timeStyle:"short"}).format(new Date(toMs(value)));
const time=(value:number)=>new Intl.DateTimeFormat("es-UY",{hour:"2-digit",minute:"2-digit"}).format(new Date(toMs(value)));
const iso=(value:number)=>new Date(toMs(value)).toISOString().slice(0,10);
const dateTimeLocal=(value:number|null)=>{if(!value)return "";const d=new Date(toMs(value));const pad=(n:number)=>String(n).padStart(2,"0");return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;};
// Dynamic category config mirrors the persisted legacy JSON shape.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const configOf=(category:Category):Record<string,any>=>{try{return category.configJson?JSON.parse(category.configJson):{};}catch{return {};}};

// API responses are intentionally generic at this boundary; callers narrow them when they consume data.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function request<T=any>(path:string,init?:RequestInit):Promise<T>{
  const response=await fetch(path,{...init,headers:{"content-type":"application/json",...init?.headers}});
  const payload=await response.json() as T&{code?:string;impact?:string};
  if(!response.ok)throw new ApiError(payload.code||`HTTP_${response.status}`,payload.impact);
  return payload;
}
async function withImpact<T>(locale:Locale,path:string,body:Record<string,unknown>):Promise<T>{
  try{return await request<T>(path,{method:"POST",body:JSON.stringify(body)});}catch(error){
    if(error instanceof ApiError&&error.code==="STRUCTURE_CHANGE_CONFIRM_REQUIRED"){
      if(!window.confirm(error.impact||text(locale,"Este cambio modifica la estructura competitiva. ¿Continuar?","This change modifies the competition structure. Continue?")))throw error;
      return request<T>(path,{method:"POST",body:JSON.stringify({...body,confirmImpact:true})});
    }
    throw error;
  }
}
async function withImpactMethod<T>(locale:Locale,path:string,method:"PUT"|"DELETE",body:Record<string,unknown>):Promise<T>{
  try{return await request<T>(path,{method,body:JSON.stringify(body)});}catch(error){
    if(error instanceof ApiError&&error.code==="STRUCTURE_CHANGE_CONFIRM_REQUIRED"){
      if(!window.confirm(error.impact||text(locale,"Este cambio modifica la estructura competitiva. ¿Continuar?","This change modifies the competition structure. Continue?")))throw error;
      return request<T>(path,{method,body:JSON.stringify({...body,confirmImpact:true})});
    }
    throw error;
  }
}

export function TournamentParityWorkspace({organizationId,tournamentId,locale,go}:Props){
  const [detail,setDetail]=useState<Detail|null>(null);const [tab,setTab]=useState<Tab>("overview");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
  const refreshTimer=useRef<number|null>(null);const stateEpoch=useRef(0);
  const load=useCallback(async()=>{const epoch=++stateEpoch.current;try{const result=await request<{ok:true}&Detail>(`/api/admin/tournaments/${tournamentId}`);if(epoch!==stateEpoch.current)return;setDetail(result);setError("");}catch(e){if(epoch===stateEpoch.current)setError(e instanceof Error?e.message:"error");}},[tournamentId]);
  const scheduleRefresh=useCallback(()=>{if(refreshTimer.current!==null)window.clearTimeout(refreshTimer.current);refreshTimer.current=window.setTimeout(()=>{refreshTimer.current=null;void load();},220);},[load]);
  useEffect(()=>{void load();return()=>{if(refreshTimer.current!==null)window.clearTimeout(refreshTimer.current);};},[load]);
  const act:ActionRunner=async(fn,afterMutation,refreshMode="background")=>{setBusy(true);setError("");try{const result=await fn();stateEpoch.current+=1;afterMutation?.(result);if(refreshMode==="blocking")await load();else if(refreshMode==="background")scheduleRefresh();return result;}catch(e){setError(e instanceof Error?e.message:"error");return undefined;}finally{setBusy(false);}};
  if(!detail)return <main className="tpw"><div className="tpw-loading">{error||"Loading…"}</div></main>;
  const tabs:Array<[Tab,string]>=[["overview",text(locale,"Resumen","Overview")],["players",text(locale,"Jugadores","Players")],["categories",text(locale,"Categorías","Categories")],["registrations",text(locale,"Inscripciones","Registrations")],["teams",text(locale,"Equipos","Teams")],["format",text(locale,"Formato","Format")],["draw",text(locale,"Sorteo","Draw")],["competition",text(locale,"Competencia","Competition")],["schedule",text(locale,"Cronograma","Schedule")],["results",text(locale,"Resultados","Results")],["tv","Modo TV"],["settings",text(locale,"Configuración","Settings")],["recovery",text(locale,"Recuperación","Recovery")]];
  return <main className="tpw">
    <button className="section-back" onClick={()=>go(`/admin/organizations/${organizationId}/tournaments`)}>← HUAU Tournament</button>
    <header className="tpw-hero"><div><div className="eyebrow">{detail.tournament.sport.toUpperCase()} · {detail.tournament.status.replaceAll("_"," ")}</div><h1>{detail.tournament.name}</h1><p>{date(detail.tournament.startAt)} · {detail.tournament.courtCount} {text(locale,"canchas","courts")} · rev. {detail.tournament.workingRevision}</p></div><div className="tpw-badges"><span className="pill">{detail.tournament.structureLocked?text(locale,"ESTRUCTURA BLOQUEADA","STRUCTURE LOCKED"):text(locale,"EN PREPARACIÓN","IN SETUP")}</span><button className="light small" onClick={()=>setTab("tv")}>Modo TV</button></div></header>
    <nav className="tpw-tabs">{tabs.map(([key,label])=><button key={key} className={tab===key?"active":""} onClick={()=>setTab(key)}>{label}</button>)}</nav>
    {error&&<div className="tpw-alert">{error}</div>}
    {tab==="overview"&&<Overview detail={detail} locale={locale} setTab={setTab}/>}
    {tab==="players"&&<Players detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="categories"&&<Categories detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="registrations"&&<TournamentRegistrationAdmin tournamentId={detail.tournament.id} locale={locale}/>} 
    {tab==="teams"&&<TeamTournamentPanel tournamentId={detail.tournament.id} locale={locale}/>}
    {tab==="format"&&<Formats detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="draw"&&<Draw detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="competition"&&<Competition detail={detail} locale={locale}/>}
    {tab==="schedule"&&<Schedule detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="results"&&<Results detail={detail} locale={locale} busy={busy} act={act}/>}
    {tab==="tv"&&<TV detail={detail} locale={locale} reload={load}/>}
    {tab==="settings"&&<SettingsPanel detail={detail} locale={locale} organizationId={organizationId} busy={busy} act={act} go={go}/>}
    {tab==="recovery"&&<Recovery detail={detail} locale={locale} busy={busy} act={act}/>}
  </main>;
}

function Overview({detail,locale,setTab}:{detail:Detail;locale:Locale;setTab:(tab:Tab)=>void}){
  const incompletePairs=detail.categories.filter(c=>c.entryType==="pair").reduce((sum,c)=>sum+pairIssues(detail,c).length,0);
  const generated=detail.categories.filter(c=>c.competitionStatus).length;const completed=detail.matches.filter(m=>m.status==="finished").length;const hasTeam=detail.categories.some(c=>c.entryType==="team");const hasStandard=detail.categories.some(c=>c.entryType!=="team");
  let step=3;
  return <section className="tpw-grid"><article className="panel wide"><div className="eyebrow">{text(locale,"PREPARACIÓN","SETUP")}</div><h2>{text(locale,"Estado operativo","Operational status")}</h2><div className="tpw-kpis"><Kpi n={detail.players.length} label={text(locale,"jugadores","players")}/><Kpi n={detail.categories.length} label={text(locale,"categorías","categories")}/><Kpi n={generated} label={text(locale,"estructuras","structures")}/><Kpi n={detail.schedule.length} label={text(locale,"bloques","slots")}/><Kpi n={completed} label={text(locale,"resultados estándar","standard results")}/></div>{incompletePairs>0&&<p className="warning-line">{incompletePairs} {text(locale,"vínculos de pareja incompletos. Revisalos antes del sorteo.","incomplete partner links. Review them before the draw.")}</p>}</article><article className="panel"><h2>{text(locale,"Flujo recomendado","Recommended flow")}</h2><div className="tpw-flow"><button onClick={()=>setTab("players")}>1 · {text(locale,"Jugadores","Players")}</button><button onClick={()=>setTab("categories")}>2 · {text(locale,"Categorías","Categories")}</button>{hasStandard&&<><button onClick={()=>setTab("format")}>{step++} · {text(locale,"Formato estándar","Standard format")}</button><button onClick={()=>setTab("draw")}>{step++} · {text(locale,"Sorteo estándar","Standard draw")}</button></>}{hasTeam&&<button onClick={()=>setTab("teams")}>{step++} · {text(locale,"Equipos y alineaciones","Teams & lineups")}</button>}<button onClick={()=>setTab("schedule")}>{step++} · {text(locale,"Cronograma","Schedule")}</button><button onClick={()=>setTab("results")}>{step} · {text(locale,"Resultados","Results")}</button></div></article></section>;
}
function Kpi({n,label}:{n:number;label:string}){return <div><strong>{n}</strong><span>{label}</span></div>}

function assignmentMap(detail:Detail,playerId:string){return new Map(detail.playerCategories.filter(a=>a.playerProfileId===playerId).map(a=>[a.categoryId,a.partnerProfileId]));}
function assignmentPayload(form:FormData,detail:Detail):Array<{categoryId:string;partnerProfileId:string|null}>{return detail.categories.filter(c=>form.get(`cat:${c.id}`)==="on").map(c=>({categoryId:c.id,partnerProfileId:c.entryType==="pair"?String(form.get(`partner:${c.id}`)||"")||null:null}));}
function pairIssues(detail:Detail,category:Category){const assignments=detail.playerCategories.filter(a=>a.categoryId===category.id);return assignments.filter(a=>!a.partnerProfileId||!assignments.some(b=>b.playerProfileId===a.partnerProfileId&&b.partnerProfileId===a.playerProfileId));}

function Players({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){
  const create=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const formElement=e.currentTarget;const form=new FormData(formElement);const body={displayName:form.get("displayName"),club:form.get("club"),contact:form.get("contact"),sportGender:form.get("sportGender"),duprSingles:Number(form.get("duprSingles")||0),duprDoubles:Number(form.get("duprDoubles")||0),paymentStatus:form.get("paymentStatus"),playerStatus:form.get("playerStatus"),notes:form.get("notes"),assignments:assignmentPayload(form,detail)};await act(()=>withImpact(locale,`/api/admin/tournaments/${detail.tournament.id}/players`,body),()=>formElement.reset());};
  return <section className="tpw-stack"><article className="panel"><div className="panel-title"><div><div className="eyebrow">{text(locale,"FICHA ÚNICA","UNIQUE PROFILE")}</div><h2>{text(locale,"Nuevo jugador","New player")}</h2></div><span>{detail.players.length}</span></div><form className="tpw-form" onSubmit={create}><div className="four"><Field n="displayName" l={text(locale,"Nombre y apellido","Full name")} required/><Field n="club" l="Club"/><Field n="contact" l={text(locale,"Contacto","Contact")}/><Select n="sportGender" l={text(locale,"Género deportivo","Sport gender")} options={[["unspecified",text(locale,"Sin especificar","Unspecified")],["male",text(locale,"Masculino","Male")],["female",text(locale,"Femenino","Female")]]}/></div><div className="four"><Field n="duprSingles" l="DUPR Singles" type="number" step="0.01"/><Field n="duprDoubles" l="DUPR Doubles" type="number" step="0.01"/><Select n="paymentStatus" l={text(locale,"Pago","Payment")} options={[["pending",text(locale,"Pendiente","Pending")],["paid",text(locale,"Pagado","Paid")]]}/><Select n="playerStatus" l={text(locale,"Estado","Status")} options={[["confirmed",text(locale,"Confirmado","Confirmed")],["pending",text(locale,"Pendiente","Pending")]]}/></div><CategoryAssignmentFields detail={detail} locale={locale}/><label><span>{text(locale,"Notas","Notes")}</span><textarea name="notes" rows={2}/></label><button className="light" disabled={busy}>{text(locale,"Agregar jugador","Add player")}</button></form></article>
    <div className="tpw-player-list">{detail.players.map(player=><PlayerCard key={player.id} player={player} detail={detail} locale={locale} busy={busy} act={act}/>)}</div>
  </section>;
}
function CategoryAssignmentFields({detail,locale,playerId}:{detail:Detail;locale:Locale;playerId?:string}){const selected=playerId?assignmentMap(detail,playerId):new Map<string,string|null>();return <fieldset className="tpw-fieldset"><legend>{text(locale,"Categorías y parejas","Categories & partners")}</legend><div className="assignment-grid">{detail.categories.filter(c=>c.entryType!=="team").map(c=><div className="assignment-item" key={c.id}><label className="check"><input type="checkbox" name={`cat:${c.id}`} defaultChecked={selected.has(c.id)}/><span>{c.name}</span></label>{c.entryType==="pair"&&<select name={`partner:${c.id}`} defaultValue={selected.get(c.id)||""}><option value="">{text(locale,"Sin pareja / pendiente","No partner / pending")}</option>{detail.players.filter(p=>p.id!==playerId).map(p=><option key={p.id} value={p.id}>{p.displayName}</option>)}</select>}</div>)}</div></fieldset>}
function PlayerCard({player,detail,locale,busy,act}:{player:Player;detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){const a=assignmentMap(detail,player.id);const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={displayName:f.get("displayName"),club:f.get("club"),contact:f.get("contact"),sportGender:f.get("sportGender"),duprSingles:Number(f.get("duprSingles")||0),duprDoubles:Number(f.get("duprDoubles")||0),paymentStatus:f.get("paymentStatus"),playerStatus:f.get("playerStatus"),notes:f.get("notes"),assignments:assignmentPayload(f,detail)};await act(()=>withImpactMethod(locale,`/api/admin/tournament-players/${player.id}`,"PUT",body));};return <article className="player-card"><div className="player-card-head"><div className="player-identity"><strong>{player.displayName}</strong><span>{player.club||text(locale,"Sin club","No club")} · {player.sportGender==="male"?"M":player.sportGender==="female"?"F":"—"} · S {player.duprSingles.toFixed(2)} · D {player.duprDoubles.toFixed(2)}</span></div><div className="player-statuses"><span className={`pill ${player.playerStatus==="confirmed"?"strong":""}`}>{player.playerStatus}</span><span className="pill">{player.paymentStatus}</span></div></div><div className="player-tags">{[...a.keys()].map(id=><span key={id}>{detail.categories.find(c=>c.id===id)?.name}</span>)}</div><details><summary>{text(locale,"Editar ficha","Edit profile")}</summary><form className="tpw-form compact-form" onSubmit={save}><div className="four"><Field n="displayName" l={text(locale,"Nombre","Name")} value={player.displayName} required/><Field n="club" l="Club" value={player.club}/><Field n="contact" l={text(locale,"Contacto","Contact")} value={player.contact}/><Select n="sportGender" l={text(locale,"Género deportivo","Sport gender")} value={player.sportGender} options={[["unspecified",text(locale,"Sin especificar","Unspecified")],["male",text(locale,"Masculino","Male")],["female",text(locale,"Femenino","Female")]]}/></div><div className="four"><Field n="duprSingles" l="DUPR Singles" type="number" step="0.01" value={String(player.duprSingles)}/><Field n="duprDoubles" l="DUPR Doubles" type="number" step="0.01" value={String(player.duprDoubles)}/><Select n="paymentStatus" l={text(locale,"Pago","Payment")} value={player.paymentStatus} options={[["pending",text(locale,"Pendiente","Pending")],["paid",text(locale,"Pagado","Paid")]]}/><Select n="playerStatus" l={text(locale,"Estado","Status")} value={player.playerStatus} options={[["confirmed",text(locale,"Confirmado","Confirmed")],["pending",text(locale,"Pendiente","Pending")]]}/></div><CategoryAssignmentFields detail={detail} locale={locale} playerId={player.id}/><label><span>{text(locale,"Notas","Notes")}</span><textarea name="notes" rows={2} defaultValue={player.notes}/></label><div className="form-actions"><button className="light small" disabled={busy}>{text(locale,"Guardar","Save")}</button><button className="danger small" type="button" disabled={busy} onClick={()=>{if(window.confirm(text(locale,"¿Eliminar este jugador del torneo?","Remove this player from tournament?")))void act(()=>withImpactMethod(locale,`/api/admin/tournament-players/${player.id}`,"DELETE",{}));}}>{text(locale,"Eliminar","Delete")}</button></div></form></details></article>}

function inferCategory(name:string){const n=name.toLowerCase();return {entryType:n.includes("single")?"individual":"pair",competitionGender:n.includes("mixto")?"mixed":n.includes("femen")?"female":n.includes("mascul")?"male":"open"};}
function Categories({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){const [preset,setPreset]=useState<string>(LEGACY_CATEGORY_PRESETS[0]);const create=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const custom=String(f.get("custom")||"").trim();const name=preset==="custom"?custom:preset;if(!name)return;const inferred=inferCategory(name);const scheduledDate=String(f.get("scheduledDate")||"");await act(()=>request(`/api/admin/tournaments/${detail.tournament.id}/categories`,{method:"POST",body:JSON.stringify({name,entryType:inferred.entryType,competitionGender:inferred.competitionGender,scheduledDate:scheduledDate||null})}));};return <section className="tpw-stack"><article className="panel"><h2>{text(locale,"Agregar categoría","Add category")}</h2><form className="inline-admin-form" onSubmit={create}><label><span>{text(locale,"Preset","Preset")}</span><select value={preset} onChange={e=>setPreset(e.target.value)}>{LEGACY_CATEGORY_PRESETS.map(v=><option key={v}>{v}</option>)}<option value="custom">{text(locale,"Personalizada…","Custom…")}</option></select></label>{preset==="custom"&&<Field n="custom" l={text(locale,"Nombre","Name")} required/>}<Field n="scheduledDate" l={text(locale,"Jornada","Day")} type="date" value={iso(detail.tournament.startAt)}/><button className="light" disabled={busy}>{text(locale,"Agregar","Add")}</button></form></article><div className="tpw-category-list">{detail.categories.map((category,index)=><CategoryCard key={category.id} category={category} index={index} detail={detail} locale={locale} busy={busy} act={act}/>)}</div></section>}
function CategoryCard({category,index,detail,locale,busy,act}:{category:Category;index:number;detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){const issues=category.entryType==="pair"?pairIssues(detail,category):[];const assigned=detail.playerCategories.filter(a=>a.categoryId===category.id).length;const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);await act(()=>withImpactMethod(locale,`/api/admin/categories/${category.id}`,"PUT",{name:f.get("name"),entryType:f.get("entryType"),competitionGender:f.get("competitionGender"),scheduledDate:f.get("scheduledDate")||null,minAge:f.get("minAge")?Number(f.get("minAge")):null,maxAge:f.get("maxAge")?Number(f.get("maxAge")):null,maxEntries:f.get("maxEntries")?Number(f.get("maxEntries")):null,registrationStatus:f.get("registrationStatus"),priceScope:f.get("priceScope"),priceMinor:f.get("priceScope")==="free"?null:Math.round(Number(f.get("price")||0)*100),currency:String(f.get("currency")||"UYU")}));};const move=(direction:"up"|"down")=>act(()=>request(`/api/admin/categories/${category.id}/order`,{method:"POST",body:JSON.stringify({direction})}));return <article className="category-card"><header><div><span className="pill">{index+1}</span><strong>{category.name}</strong><small>{assigned} {text(locale,"jugadores asignados","assigned players")} · {category.entryCount} {text(locale,"entradas válidas","valid entries")}</small></div><div className="order-buttons"><button disabled={busy||index===0} onClick={()=>void move("up")}>↑</button><button disabled={busy||index===detail.categories.length-1} onClick={()=>void move("down")}>↓</button></div></header>{issues.length>0&&<p className="warning-line">{issues.length} {text(locale,"jugadores sin pareja recíproca; no entrarán al sorteo.","players without reciprocal partner; they will not enter the draw.")}</p>}<details><summary>{text(locale,"Editar categoría","Edit category")}</summary><form className="tpw-form" onSubmit={save}><div className="four"><Field n="name" l={text(locale,"Nombre","Name")} value={category.name} required/><Select n="entryType" l={text(locale,"Modalidad","Mode")} value={category.entryType} options={category.entryType==="team"?[["team",text(locale,"Equipo","Team")]]:[["individual",text(locale,"Individual","Individual")],["pair",text(locale,"Pareja","Pair")]]}/><Select n="competitionGender" l={text(locale,"Género","Gender")} value={category.competitionGender||"open"} options={[["open","Open"],["male",text(locale,"Masculino","Male")],["female",text(locale,"Femenino","Female")],["mixed",text(locale,"Mixto","Mixed")]]}/><Field n="scheduledDate" l={text(locale,"Jornada","Day")} type="date" value={category.scheduledDate||iso(detail.tournament.startAt)}/></div><div className="registration-category-settings"><div className="eyebrow">ONLINE REGISTRATION</div><div className="four"><Select n="registrationStatus" l={text(locale,"Inscripción","Registration")} value={category.registrationStatus||"closed"} options={[["closed",text(locale,"Cerrada","Closed")],["open",text(locale,"Abierta","Open")],["waitlist_only","Waitlist only"]]}/><Field n="maxEntries" l={text(locale,"Cupo (vacío = sin límite)","Capacity (blank = unlimited)")} type="number" value={category.maxEntries===null?"":String(category.maxEntries)}/><Field n="minAge" l={text(locale,"Edad mínima","Minimum age")} type="number" value={category.minAge===null?"":String(category.minAge)}/><Field n="maxAge" l={text(locale,"Edad máxima","Maximum age")} type="number" value={category.maxAge===null?"":String(category.maxAge)}/></div><div className="three"><Select n="priceScope" l={text(locale,"Precio","Price")} value={category.priceScope||"free"} options={[["free",text(locale,"Gratis","Free")],["per_entry",text(locale,"Por inscripción","Per entry")],["per_person",text(locale,"Por persona","Per person")]]}/><Field n="price" l={text(locale,"Importe","Amount")} type="number" step="1" value={category.priceMinor===null?"":String(category.priceMinor/100)}/><Field n="currency" l={text(locale,"Moneda","Currency")} value={category.currency||"UYU"}/></div><p className="muted">{text(locale,"Para +40 / +50 / +60 usá Edad mínima explícita. HUAU calcula la edad a la fecha de inicio del torneo.","For +40 / +50 / +60 use an explicit minimum age. HUAU calculates age at tournament start.")}</p></div><div className="form-actions"><button className="light small" disabled={busy}>{text(locale,"Guardar","Save")}</button><button className="danger small" type="button" disabled={busy} onClick={()=>{if(window.confirm(text(locale,"¿Eliminar esta categoría?","Delete this category?")))void act(()=>withImpactMethod(locale,`/api/admin/categories/${category.id}`,"DELETE",{}));}}>{text(locale,"Eliminar","Delete")}</button></div></form></details></article>}
function Formats({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){return <section className="tpw-stack"><FreeFormatSimulator detail={detail} locale={locale}/>{detail.categories.filter(category=>category.entryType!=="team").map(category=><FormatSimulator key={category.id} detail={detail} category={category} locale={locale} busy={busy} act={act}/>)}</section>}
function FreeFormatSimulator({detail,locale}:{detail:Detail;locale:Locale}){
  const [options,setOptions]=useState<LegacyFormatOption[]>([]);
  const simulate=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const entries=Math.max(2,Number(f.get("entries")||2));const courts=Math.max(1,Number(f.get("courts")||detail.tournament.courtCount));const matchMinutes=Math.max(5,Number(f.get("matchMinutes")||detail.settings.defaultMatchMinutes));const availableMinutes=Math.max(0,Number(f.get("availableMinutes")||minsBetween(detail.settings.dailyStart,detail.settings.dailyEnd)));setOptions(buildLegacyFormatOptions({entries,courts,availableMinutes,matchMinutes,minimumGroup:detail.settings.minimumGroup,preferredGroup:detail.settings.preferredGroup,maximumGroup:detail.settings.maximumGroup,finalDrawMethod:"performance",avoidGroupRematches:true,bronzeMatch:true,medalBestOf:3,medalSchedule:"sequential",standardPointTarget:15,medalPointTarget:11,groupRounds:1,crossGroupMethod:"normalized",playoffMode:"standard",consolationMode:"none",minimumGuaranteedMatches:0,wildcardQualifiers:0,requestedQualifiersPerGroup:detail.settings.suggestedQualifiersPerGroup as 0|1|2}));};
  return <article className="panel format-simulator"><div className="panel-title"><div><div className="eyebrow">{text(locale,"SIMULADOR LIBRE","FREE SIMULATOR")}</div><h2>{text(locale,"Probar un formato sin modificar categorías","Test a format without changing categories")}</h2><p>{text(locale,"Replica el simulador libre del Tournament original; ninguna opción se guarda hasta aplicarla dentro de una categoría.","Mirrors the legacy free simulator; nothing is saved until applied inside a category.")}</p></div></div><form className="inline-admin-form" onSubmit={simulate}><Field n="entries" l={text(locale,"Participantes / parejas","Players / pairs")} type="number" value="12"/><Field n="courts" l={text(locale,"Canchas","Courts")} type="number" value={String(detail.tournament.courtCount)}/><Field n="matchMinutes" l={text(locale,"Min/partido","Min/match")} type="number" value={String(detail.settings.defaultMatchMinutes)}/><Field n="availableMinutes" l={text(locale,"Min disponibles","Available min")} type="number" value={String(minsBetween(detail.settings.dailyStart,detail.settings.dailyEnd))}/><button className="ghost">{text(locale,"Simular","Simulate")}</button></form>{options.length>0&&<div className="format-options compact-options">{options.map(o=><FormatOptionCard key={o.label} option={o} locale={locale}/>)}</div>}</article>
}
function minsBetween(a:string,b:string){const [ah=0,am=0]=a.split(":").map(Number);const [bh=0,bm=0]=b.split(":").map(Number);return Math.max(0,(bh*60+bm)-(ah*60+am));}
function FormatSimulator({detail,category,locale,busy,act}:{detail:Detail;category:Category;locale:Locale;busy:boolean;act:ActionRunner}){const saved=configOf(category);const [options,setOptions]=useState<LegacyFormatOption[]>([]);const simulate=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload=formatFormPayload(f,detail,category);const r=await request<{options:LegacyFormatOption[]}>(`/api/admin/categories/${category.id}/format/simulate`,{method:"POST",body:JSON.stringify(payload)});setOptions(r.options);};const apply=async(option:LegacyFormatOption)=>{const config={...option,groupCount:option.groups,groupSizes:option.sizes,matchMinutes:option.matchMinutes,seedingMethod:saved.seedingMethod||detail.settings.seedingMethod,preferredRestSlots:Number(saved.preferredRestSlots??detail.settings.minimumRestSlots),dailyStart:detail.settings.dailyStart};await act(()=>withImpactMethod(locale,`/api/admin/categories/${category.id}/format`,"PUT",{config}));setOptions([]);};return <article className="panel format-simulator"><div className="panel-title"><div><div className="eyebrow">{text(locale,"SIMULADOR DE FORMATO","FORMAT SIMULATOR")}</div><h2>{category.name}</h2><p>{category.entryCount} {text(locale,"entradas válidas","valid entries")}</p></div>{category.formatVersionId&&<span className="pill strong">{text(locale,"FORMATO GUARDADO","SAVED")}</span>}</div><form className="tpw-form" onSubmit={simulate}><div className="four"><Field n="matchMinutes" l={text(locale,"Min/partido","Min/match")} type="number" value={String(saved.matchMinutes??detail.settings.defaultMatchMinutes)}/><Field n="minimumGuaranteedMatches" l={text(locale,"Mín. partidos garantizados","Min guaranteed matches")} type="number" value={String(saved.minimumGuaranteedMatches??0)}/><Select n="groupRounds" l={text(locale,"Vueltas","Rounds")} value={String(saved.groupRounds??1)} options={[["1","1"],["2","2"]]}/><Select n="requestedQualifiersPerGroup" l={text(locale,"Clasificados/grupo","Qualifiers/group")} value={String(saved.qualifiersPerGroup??0)} options={[["0","Auto"],["1","1"],["2","2"]]}/></div><div className="four"><Field n="wildcardQualifiers" l="Wildcards" type="number" value={String(saved.wildcardQualifiers??0)}/><Select n="crossGroupMethod" l={text(locale,"Comparación entre grupos","Cross-group comparison")} value={String(saved.crossGroupMethod??"normalized")} options={[["normalized",text(locale,"Normalizada","Normalized")],["equalized",text(locale,"Equiparada","Equalized")]]}/><Select n="playoffMode" l={text(locale,"Fase posterior","Post-group phase")} value={String(saved.playoffMode??"standard")} options={[["standard",text(locale,"Cuadro estándar","Standard bracket")],["top2_final","Top 2 → Final"],["top4_semis","Top 4 → Semis"],["top3_step","Top 3 step ladder"],["league_only",text(locale,"Campeón por tabla","Table champion")]]}/><Select n="consolationMode" l={text(locale,"Consuelo","Consolation")} value={String(saved.consolationMode??"none")} options={[["none",text(locale,"Sin consuelo","None")],["knockout",text(locale,"Cuadro consuelo","Consolation bracket")]]}/></div><details className="advanced"><summary>{text(locale,"Opciones avanzadas","Advanced options")}</summary><div className="four"><Select n="finalDrawMethod" l={text(locale,"Cruce fase final","Final draw")} value={String(saved.finalDrawMethod??"performance")} options={[["performance",text(locale,"Por rendimiento","Performance")],["pots",text(locale,"Bombos","Pots")]]}/><Select n="avoidGroupRematches" l={text(locale,"Revancha inmediata","Immediate rematch")} value={saved.avoidGroupRematches===false?"no":"yes"} options={[["yes",text(locale,"Evitar si es posible","Avoid if possible")],["no",text(locale,"Permitir","Allow")]]}/><Select n="bronzeMatch" l={text(locale,"Partido por bronce","Bronze match")} value={saved.bronzeMatch?"yes":"no"} options={[["no",text(locale,"No","No")],["yes",text(locale,"Sí","Yes")]]}/><Select n="medalSchedule" l={text(locale,"Orden medallas","Medal order")} value={String(saved.medalSchedule??"sequential")} options={[["sequential",text(locale,"Bronce y luego final","Bronze then final")],["simultaneous",text(locale,"Simultáneos","Simultaneous")]]}/></div><div className="four"><Select n="medalBestOf" l="BO final / bronce" value={String(saved.medalBestOf??saved.medal?.bestOf??3)} options={[["1","BO1"],["3","BO3"]]}/><Field n="standardPointTarget" l={text(locale,"Puntos fase grupos","Group points")} type="number" value={String(saved.standardPointTarget??saved.preliminary?.pointTarget??15)}/><Field n="medalPointTarget" l={text(locale,"Puntos medallas","Medal points")} type="number" value={String(saved.medalPointTarget??saved.medal?.pointTarget??11)}/><Field n="preferredRestSlots" l={text(locale,"Descanso preferido (bloques)","Preferred rest (slots)")} type="number" value={String(saved.preferredRestSlots??detail.settings.minimumRestSlots)}/></div></details><div className="simulator-context"><span>{detail.tournament.courtCount} {text(locale,"canchas","courts")}</span><span>{detail.settings.dailyStart}–{detail.settings.dailyEnd}</span><span>{minsBetween(detail.settings.dailyStart,detail.settings.dailyEnd)} min</span><span>{text(locale,"Grupos objetivo","Group target")}: {detail.settings.minimumGroup}/{detail.settings.preferredGroup}/{detail.settings.maximumGroup}</span></div><button className="ghost" disabled={busy||category.entryCount<2}>{text(locale,"Simular opciones","Simulate options")}</button></form>{options.length>0&&<div className="format-options">{options.map(option=><FormatOptionCard key={option.label} option={option} locale={locale} action={<button className="light" disabled={busy} onClick={()=>void apply(option)}>{text(locale,"Usar este formato","Use this format")}</button>}/>)}</div>}</article>}
function FormatOptionCard({option,locale,action}:{option:LegacyFormatOption;locale:Locale;action?:ReactNode}){
  const groupNames=option.sizes.map((size,index)=>`${text(locale,"Grupo","Group")} ${String.fromCharCode(65+index)}: ${size}`).join(" · ");
  const duration=`${Math.floor(option.elapsedMinutes/60)} h ${String(option.elapsedMinutes%60).padStart(2,"0")} min`;
  const playoffLabel=option.playoffMode==="standard"?text(locale,"Cuadro estándar","Standard bracket"):option.playoffMode==="top2_final"?"Top 2 → Final":option.playoffMode==="top4_semis"?"Top 4 → Semis":option.playoffMode==="top3_step"?"Top 3 step ladder":text(locale,"Campeón por tabla","Table champion");
  return <article className={`format-option-card ${option.label==="Recomendada"?"recommended":""}`}>
    <header className="format-option-head"><span className="format-option-label">{option.label}</span><span className={`format-fit ${option.fits?"good":"bad"}`}>{option.fits?text(locale,"Entra en horario","Fits schedule"):text(locale,"Excede horario","Over schedule")}</span></header>
    <h3>{option.groups} {text(locale,"grupos","groups")}</h3><p className="format-group-sizes">{groupNames}</p>
    <div className="format-stat-grid"><div><strong>{option.guaranteed}</strong><span>{text(locale,"partidos mínimos","minimum matches")}</span></div><div><strong>{option.totalMatches}</strong><span>{text(locale,"partidos totales","total matches")}</span></div><div><strong>{duration}</strong><span>{text(locale,"duración estimada","estimated duration")}</span></div><div><strong>{option.qualified}</strong><span>{text(locale,"clasificación","qualification")}</span></div></div>
    <div className="format-detail-list"><span>{option.groupRounds} {option.groupRounds===1?text(locale,"vuelta en grupos","group round"):text(locale,"vueltas en grupos","group rounds")}</span><span>{text(locale,"Fase de grupos","Group stage")}: {option.groupMatches}</span><span>{text(locale,"Fase principal","Main phase")}: {option.finalMatches}</span><span>{text(locale,"Clasifican","Qualify")} {option.qualifiersPerGroup} {text(locale,"por grupo","per group")}{option.wildcardQualifiers?` + ${option.wildcardQualifiers} wildcard`:""}</span><span>{text(locale,"Comparación","Comparison")} {option.crossGroupMethod==="equalized"?text(locale,"equiparada","equalized"):text(locale,"normalizada","normalized")}</span><span>{text(locale,"Fase previa","Group scoring")}: 1 set a {option.standardPointTarget} {text(locale,"puntos","points")}</span><span>{text(locale,"Final y bronce","Final & bronze")}: {option.medalBestOf===3?text(locale,"mejor de 3","best of 3"):text(locale,"un partido","single match")} a {option.medalPointTarget}</span></div>
    <div className="format-explanation"><strong>{playoffLabel}</strong><p>{text(locale,"Los clasificados se ordenan por posición de grupo y rendimiento. HUAU aplica los cruces, byes, revancha de grupo y medallas según las reglas elegidas.","Qualified entries are ordered by group position and performance. HUAU applies pairings, byes, group-rematch rules and medal matches from the selected rules.")}</p></div>
    {action&&<div className="format-option-action">{action}</div>}
  </article>;
}

function formatFormPayload(f:FormData,detail:Detail,category:Category){return {courts:detail.tournament.courtCount,availableMinutes:minsBetween(detail.settings.dailyStart,detail.settings.dailyEnd),matchMinutes:Number(f.get("matchMinutes")),minimumGroup:detail.settings.minimumGroup,preferredGroup:detail.settings.preferredGroup,maximumGroup:detail.settings.maximumGroup,minimumGuaranteedMatches:Number(f.get("minimumGuaranteedMatches")),groupRounds:Number(f.get("groupRounds")),requestedQualifiersPerGroup:Number(f.get("requestedQualifiersPerGroup")),wildcardQualifiers:Number(f.get("wildcardQualifiers")),crossGroupMethod:f.get("crossGroupMethod"),playoffMode:f.get("playoffMode"),consolationMode:f.get("consolationMode"),finalDrawMethod:f.get("finalDrawMethod"),avoidGroupRematches:f.get("avoidGroupRematches")==="yes",bronzeMatch:f.get("bronzeMatch")==="yes",medalSchedule:f.get("medalSchedule"),medalBestOf:Number(f.get("medalBestOf")),standardPointTarget:Number(f.get("standardPointTarget")),medalPointTarget:Number(f.get("medalPointTarget")),preferredRestSlots:Number(f.get("preferredRestSlots")),categoryId:category.id};}

function Draw({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){
  const standardCategories=detail.categories.filter(category=>category.entryType!=="team");
  const batch=()=>act(async()=>{for(const category of standardCategories){const config=configOf(category);if(!category.formatVersionId||category.entryCount<2)continue;const method=(config.seedingMethod||detail.settings.seedingMethod) as LegacySeedingMethod;if(method==="manual"||method==="live")continue;const sizes=(Array.isArray(config.groupSizes)?config.groupSizes:[category.entryCount]).map(Number);await withImpact(locale,`/api/admin/categories/${category.id}/groups`,{seedingMethod:method,groupSizes:sizes,config:{...config,seedingMethod:method,groupSizes:sizes},scheduledDate:category.scheduledDate||iso(detail.tournament.startAt)});}});
  const ready=standardCategories.filter(c=>c.formatVersionId&&c.entryCount>=2&&!["manual","live"].includes(String(configOf(c).seedingMethod||detail.settings.seedingMethod))).length;
  return <section className="tpw-stack"><article className="panel"><div className="panel-title"><div><div className="eyebrow">{text(locale,"GENERACIÓN MASIVA","BATCH GENERATION")}</div><h2>{text(locale,"Generar todas las categorías listas","Generate all ready categories")}</h2><p>{text(locale,"Respeta el método guardado. Manual y Sorteo en Vivo se confirman individualmente.","Uses each saved method. Manual and Live Draw are confirmed individually.")}</p></div><button className="light small" disabled={busy||ready===0} onClick={()=>void batch()}>{text(locale,`Generar ${ready} listas`,`Generate ${ready} ready`)}</button></div></article>{standardCategories.map(category=><DrawCategory key={category.id} detail={detail} category={category} locale={locale} busy={busy} act={act}/>)}</section>
}
function DrawCategory({detail,category,locale,busy,act}:{detail:Detail;category:Category;locale:Locale;busy:boolean;act:ActionRunner}){const config=configOf(category);const entries=detail.entries.filter(e=>e.categoryId===category.id);const sizes=(Array.isArray(config.groupSizes)?config.groupSizes:[category.entryCount]).map(Number);const [method,setMethod]=useState<LegacySeedingMethod>(config.seedingMethod||detail.settings.seedingMethod||"snake");const [manual,setManual]=useState<string[]>(()=>manualSuggestion(entries,sizes));useEffect(()=>setManual(manualSuggestion(entries,sizes)),[category.entryCount,category.formatVersionId]);const generate=async()=>{if(method==="live")return;await act(()=>withImpact(locale,`/api/admin/categories/${category.id}/groups`,{seedingMethod:method,groupSizes:sizes,orderedEntryIds:method==="manual"?manual:undefined,config:{...config,seedingMethod:method,groupSizes:sizes},scheduledDate:category.scheduledDate||iso(detail.tournament.startAt)}));};const session=detail.drawSessions.find(s=>s.categoryId===category.id);return <article className="panel"><div className="panel-title"><div><div className="eyebrow">{text(locale,"SIEMBRA Y SORTEO","SEEDING & DRAW")}</div><h2>{category.name}</h2><p>{entries.length} {text(locale,"entradas","entries")} · {sizes.length} {text(locale,"grupos","groups")} · {sizes.join(" / ")}</p></div>{category.structureLocked&&<span className="pill strong">{text(locale,"BLOQUEADO","LOCKED")}</span>}</div>{!category.formatVersionId?<div className="empty-state">{text(locale,"Primero guardá un formato desde la pestaña Formato.","Save a format first in the Format tab.")}</div>:<><div className="draw-methods"><button className={method==="snake"?"active":""} onClick={()=>setMethod("snake")}>{text(locale,"DUPR serpentina","DUPR snake")}</button><button className={method==="random"?"active":""} onClick={()=>setMethod("random")}>{text(locale,"Aleatorio","Random")}</button><button className={method==="manual"?"active":""} onClick={()=>setMethod("manual")}>{text(locale,"Manual","Manual")}</button><button className={method==="live"?"active":""} onClick={()=>setMethod("live")}>{text(locale,"Sorteo en vivo","Live draw")}</button></div>{method==="manual"&&<ManualGroups entries={entries} sizes={sizes} order={manual} setOrder={setManual} locale={locale}/>} {method==="live"?<LiveDraw category={category} sizes={sizes} session={session} entries={entries} locale={locale} busy={busy} act={act}/>:<button className="light" disabled={busy||entries.length<2||sizes.reduce((a,b)=>a+b,0)!==entries.length} onClick={()=>void generate()}>{category.structureLocked?text(locale,"Regenerar con snapshot","Regenerate with snapshot"):text(locale,"Confirmar grupos","Confirm groups")}</button>}</>}</article>}
function manualSuggestion(entries:Entry[],sizes:number[]){const sorted=[...entries].sort((a,b)=>b.seedRating-a.seedRating||a.displayName.localeCompare(b.displayName));const groups=sizes.map(()=>[] as Entry[]);let i=0,row=0;while(i<sorted.length){const indices=row%2===0?groups.map((_,x)=>x):groups.map((_,x)=>groups.length-1-x);for(const gi of indices){if(i>=sorted.length)break;if(groups[gi]!.length>=sizes[gi]!)continue;groups[gi]!.push(sorted[i++]!);}row++;if(row>sorted.length*3)break;}return groups.flat().map(e=>e.id);}
function ManualGroups({entries,sizes,order,setOrder,locale}:{entries:Entry[];sizes:number[];order:string[];setOrder:(v:string[])=>void;locale:Locale}){let cursor=0;return <div className="manual-groups">{sizes.map((size,gi)=>{const start=cursor;cursor+=size;return <div key={gi}><h4>{text(locale,"Grupo","Group")} {String.fromCharCode(65+gi)}</h4>{Array.from({length:size},(_,slot)=>{const idx=start+slot;return <select key={slot} value={order[idx]||""} onChange={e=>{const value=e.target.value;const next=[...order];const existing=next.indexOf(value);if(existing>=0)[next[idx],next[existing]]=[next[existing]!,next[idx]!];else next[idx]=value;setOrder(next);}}><option value="">—</option>{entries.map(entry=><option key={entry.id} value={entry.id}>{entry.displayName} · {entry.seedRating.toFixed(2)}</option>)}</select>})}</div>})}<button className="ghost small" type="button" onClick={()=>setOrder(manualSuggestion(entries,sizes))}>{text(locale,"Sugerencia automática","Automatic suggestion")}</button></div>}
function LiveDraw({category,sizes,session,entries,locale,busy,act}:{category:Category;sizes:number[];session:DrawSession|undefined;entries:Entry[];locale:Locale;busy:boolean;act:ActionRunner}){
  const parsedSession=useMemo(()=>{try{return session?JSON.parse(session.stateJson) as LiveDrawState:null}catch{return null}},[session]);
  const [state,setState]=useState<LiveDrawState|null>(parsedSession);const [auto,setAuto]=useState(false);
  useEffect(()=>{if(parsedSession)setState(parsedSession);},[parsedSession?.revealIndex,parsedSession?.status,session?.updatedAt]);
  const runLocal=(path:string,body:string)=>act(()=>request<LiveDrawResponse>(path,{method:"POST",body}),result=>setState(result.state),"none");
  useEffect(()=>{if(!auto||!state||state.status==="complete")return;const timer=window.setTimeout(()=>void runLocal(`/api/admin/categories/${category.id}/draw/next`,"{}"),1350);return()=>window.clearTimeout(timer)},[auto,state?.revealIndex,state?.status,category.id]);
  const entryName=(id:string)=>entries.find(e=>e.id===id)?.displayName||id;
  const start=()=>runLocal(`/api/admin/categories/${category.id}/draw/start`,JSON.stringify({groupSizes:sizes}));
  const next=()=>runLocal(`/api/admin/categories/${category.id}/draw/next`,"{}");
  const reset=()=>runLocal(`/api/admin/categories/${category.id}/draw/reset`,JSON.stringify({groupSizes:sizes}));
  return <div className="live-draw">{!state?<button className="light" disabled={busy} onClick={()=>void start()}>{text(locale,"Iniciar sorteo en vivo","Start live draw")}</button>:<><div className="draw-reveal"><span>{state.lastGroup?`${text(locale,"Grupo","Group")} ${state.lastGroup}`:text(locale,"Listo para comenzar","Ready")}</span><strong>{state.lastEntryId?entryName(state.lastEntryId):"HUAU"}</strong><small>{state.revealIndex}/{state.entryOrder.length}</small></div><div className="draw-groups">{(Object.entries(state.assignments) as Array<[string,string[]]>).map(([label,ids])=><div key={label}><b>{text(locale,"Grupo","Group")} {label}</b>{ids.map(id=><span key={id}>{entryName(id)}</span>)}</div>)}</div><div className="form-actions"><button className="light small" disabled={busy||state.status==="complete"} onClick={()=>void next()}>{text(locale,"Sacar siguiente","Draw next")}</button><button className="ghost small" disabled={state.status==="complete"} onClick={()=>setAuto(v=>!v)}>{auto?text(locale,"Pausar","Pause"):text(locale,"Automático","Auto")}</button><button className="ghost small" disabled={busy} onClick={()=>void reset()}>{text(locale,"Mezclar / reiniciar","Reshuffle / reset")}</button>{state.status==="complete"&&<button className="light small" disabled={busy} onClick={()=>void act(()=>withImpact(locale,`/api/admin/categories/${category.id}/draw/confirm`,{}))}>{text(locale,"Confirmar grupos","Confirm groups")}</button>}</div></>}</div>
}

function Competition({detail,locale}:{detail:Detail;locale:Locale}){return <section className="tpw-stack">{detail.categories.filter(category=>category.entryType!=="team").map(category=>{const groups=grouped(detail,category.id);const finals=detail.matches.filter(m=>m.categoryId===category.id&&m.stage!=="group");return <article className="panel" key={category.id}><div className="panel-title"><div><div className="eyebrow">{text(locale,"COMPETENCIA","COMPETITION")}</div><h2>{category.name}</h2></div><span>{groups.length} {text(locale,"grupos","groups")}</span></div>{groups.length===0?<div className="empty-state">{text(locale,"Todavía no hay grupos confirmados.","No confirmed groups yet.")}</div>:<div className="competition-groups">{groups.map(group=><StandingsCard key={group.id} detail={detail} categoryId={category.id} groupId={group.id} groupName={group.name} entries={group.entries} locale={locale}/>)}</div>}{groups.length>1&&<CrossTable detail={detail} categoryId={category.id} locale={locale}/>} {finals.length>0&&<div className="bracket"><h3>{text(locale,"Fase final","Final phase")}</h3>{finals.map(m=><div className="bracket-row" key={m.encounterId}><span>{m.roundLabel||m.stage}</span><strong>{m.sideA||text(locale,"Por definir","TBD")} <em>vs</em> {m.sideB||text(locale,"Por definir","TBD")}</strong><small>{m.status}</small></div>)}</div>}</article>})}<TeamCompetitionPanel tournamentId={detail.tournament.id} locale={locale}/></section>}
function grouped(detail:Detail,categoryId:string){const map=new Map<string,{id:string;name:string;entries:string[]}>();detail.groups.filter(g=>g.categoryId===categoryId).forEach(row=>{const group=map.get(row.id)||{id:row.id,name:row.name,entries:[]};if(row.entryName)group.entries.push(row.entryName);map.set(row.id,group)});return [...map.values()]}
function StandingsCard({detail,categoryId,groupId,groupName,entries,locale}:{detail:Detail;categoryId:string;groupId:string;groupName:string;entries:string[];locale:Locale}){const standing=detail.standings.find(s=>s.categoryId===categoryId&&s.groupId===groupId);return <div className="standings-card"><h3>{text(locale,"Grupo","Group")} {groupName}</h3>{standing?.rows?.length?<table><thead><tr><th>#</th><th>{text(locale,"Entrada","Entry")}</th><th>PJ</th><th>PG</th><th>PP</th><th>PF</th><th>PC</th><th>DIF</th></tr></thead><tbody>{standing.rows.map(r=><tr key={r.entryId}><td>{r.position}</td><td>{r.name}</td><td>{r.played}</td><td>{r.wins}</td><td>{r.losses}</td><td>{r.scored}</td><td>{r.conceded}</td><td>{r.diff>0?`+${r.diff}`:r.diff}</td></tr>)}</tbody></table>:<div className="simple-entry-list">{entries.map(e=><span key={e}>{e}</span>)}</div>}</div>}
function CrossTable({detail,categoryId,locale}:{detail:Detail;categoryId:string;locale:Locale}){const rows=detail.crossGroup.filter(r=>r.categoryId===categoryId).sort((a,b)=>a.position-b.position||b.winRate-a.winRate||b.diffPerMatch-a.diffPerMatch);if(!rows.length)return null;return <details className="cross-table"><summary>{text(locale,"Comparación entre grupos","Cross-group comparison")}</summary><table><thead><tr><th>{text(locale,"Entrada","Entry")}</th><th>G</th><th>Pos</th><th>PJ</th><th>%</th><th>Dif/P</th><th>PF/P</th></tr></thead><tbody>{rows.map(r=><tr key={`${r.groupId}:${r.entryId}`}><td>{r.name}</td><td>{r.groupName}</td><td>{r.position}</td><td>{r.played}</td><td>{Math.round(r.winRate*100)}%</td><td>{r.diffPerMatch.toFixed(2)}</td><td>{r.scoredPerMatch.toFixed(2)}</td></tr>)}</tbody></table><p>{rows[0]?.method==="equalized"?text(locale,"Equiparada: para comparar grupos de distinto tamaño se excluyen únicamente de la comparación cruzada los partidos extra.","Equalized: extra matches are excluded only from cross-group comparison."):text(locale,"Normalizada: se comparan porcentaje de victorias, diferencia y puntos por partido.","Normalized: win rate, point differential and points per match are compared.")}</p></details>}

function Schedule({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){
  const byCategory=detail.categories.map(c=>({category:c,rows:detail.schedule.filter(s=>s.categoryId===c.id)})).filter(x=>x.rows.length);
  const saveRest=(value:number)=>act(()=>request(`/api/admin/tournaments/${detail.tournament.id}/settings`,{method:"PUT",body:JSON.stringify({minimumRestSlots:value})}));
  return <section className="tpw-stack"><article className="panel"><div className="panel-title"><div><h2>{text(locale,"Cronograma operativo","Operational schedule")}</h2><p>{text(locale,"Partidos reales, reservas de fase final, horarios y canchas en orden cronológico. El descanso es global, como en Tournament V2.4.2.","Real matches, final reservations, times and courts in chronological order. Rest is tournament-wide, as in Tournament V2.4.2.")}</p></div><div className="form-actions"><label className="compact-select"><span>{text(locale,"Descanso","Rest")}</span><select value={String(detail.settings.minimumRestSlots)} onChange={e=>void saveRest(Number(e.target.value))} disabled={busy}><option value="0">0</option><option value="1">1</option><option value="2">2</option></select></label><button className="ghost small" disabled={busy} onClick={()=>void act(()=>request(`/api/admin/tournaments/${detail.tournament.id}/schedule/regenerate`,{method:"POST",body:"{}"}))}>{text(locale,"Regenerar","Regenerate")}</button></div></div></article>{byCategory.map(({category,rows})=><article className="panel schedule-category" key={category.id}><div className="panel-title"><div><h2>{category.name}</h2><span>{rows.length} {text(locale,"bloques","slots")}</span></div><div className="form-actions"><strong>{dt(rows[0]!.startAt)} → {time(rows[rows.length-1]!.endAt)}</strong><button className="ghost small" onClick={()=>downloadScheduleImages(detail,locale,category.id)}>{text(locale,"Imagen","Image")}</button></div></div><div className="schedule-list">{rows.map(row=><div className={`schedule-row ${row.status==="reserved"?"reserved":""} ${row.categoryEntryType==="team"?"team-schedule-row":""}`} key={row.id}><time>{dt(row.startAt)}</time><b>{row.courtLabel}</b><div><strong>{row.sideA&&row.sideB?`${row.sideA} — ${row.sideB}`:text(locale,"Reserva de fase","Stage reservation")}</strong><span>{row.categoryEntryType==="team"?`TEAM · ${row.groupName?`${text(locale,"Grupo","Group")} ${row.groupName} · `:""}${row.roundLabel||row.rubberKey||"Rubber"}${row.bestOf?` · BO${row.bestOf}`:""}`:`${row.groupName?`${text(locale,"Grupo","Group")} ${row.groupName}`:row.roundLabel||row.stage}${row.legNumber&&row.legNumber>1?` · V${row.legNumber}`:""}`}</span></div><small>{row.status}</small></div>)}</div></article>)}{!byCategory.length&&<div className="empty-state">{text(locale,"Generá grupos para construir el cronograma.","Generate groups to build the schedule.")}</div>}</section>
}

function Results({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){const playable=detail.matches.filter(m=>m.matchId&&m.sideA&&m.sideB&&m.status!=="bye");const pending=playable.filter(m=>m.status!=="finished");const completed=playable.filter(m=>m.status==="finished").sort((a,b)=>Number(b.scheduleStart??0)-Number(a.scheduleStart??0));return <section className="tpw-stack"><article className="panel"><div className="panel-title"><div><h2>{text(locale,"Resultados por cronograma","Results by schedule")}</h2><p>{text(locale,"El primer pendiente es el próximo partido operativo. Las categorías Team aparecen debajo con sus rubbers en el mismo orden del cronograma global.","The first pending match is the next operational match. Team categories appear below with rubbers in the same global schedule order.")}</p></div><span>{completed.length}/{playable.length}</span></div><div className="results-section"><h3>{text(locale,"Pendientes estándar","Standard pending")}</h3>{pending.length?pending.map((m,i)=><ScoreRow key={m.encounterId} match={m} next={i===0} locale={locale} busy={busy} act={act}/>):<div className="empty-state">{text(locale,"No quedan partidos estándar pendientes.","No pending standard matches.")}</div>}</div>{completed.length>0&&<details className="completed-results"><summary>{text(locale,"Resultados estándar cargados","Completed standard results")} · {completed.length}</summary>{completed.map(m=><ScoreRow key={m.encounterId} match={m} locale={locale} busy={busy} act={act}/>)}</details>}</article><TeamResultsPanel tournamentId={detail.tournament.id} locale={locale}/>{detail.categories.filter(c=>c.entryType!=="team").map(c=>{const groups=grouped(detail,c.id);return groups.length?<article className="panel" key={c.id}><h2>{c.name} · {text(locale,"Tablas en vivo","Live standings")}</h2><div className="competition-groups">{groups.map(g=><StandingsCard key={g.id} detail={detail} categoryId={c.id} groupId={g.id} groupName={g.name} entries={g.entries} locale={locale}/>)}</div>{groups.length>1&&<CrossTable detail={detail} categoryId={c.id} locale={locale}/>}</article>:null})}</section>}
function ScoreRow({match,next=false,locale,busy,act}:{match:Match;next?:boolean;locale:Locale;busy:boolean;act:ActionRunner}){const [a,setA]=useState(match.scoreA===null?"":String(match.scoreA));const [b,setB]=useState(match.scoreB===null?"":String(match.scoreB));const [sets,setSets]=useState(()=>[0,1,2].map(i=>({a:match.sets?.[i]?.scoreA===undefined?"":String(match.sets[i]!.scoreA),b:match.sets?.[i]?.scoreB===undefined?"":String(match.sets[i]!.scoreB)})));const save=async(e:FormEvent)=>{e.preventDefault();const body=match.bestOf===3?{sets:sets.filter(s=>s.a!==""&&s.b!=="").map(s=>({scoreA:Number(s.a),scoreB:Number(s.b)}))}:{scoreA:Number(a),scoreB:Number(b)};await act(()=>withImpact(locale,`/api/admin/matches/${match.matchId}/result`,body));};return <form className={`score-row ${next?"next":""}`} onSubmit={save}><div className="match-meta">{next&&<span className="next-label">{text(locale,"SIGUIENTE","NEXT")}</span>}<strong>{match.scheduleStart?dt(match.scheduleStart):match.categoryName}</strong><span>{match.courtLabel||""} · {match.groupName?`${text(locale,"Grupo","Group")} ${match.groupName}`:match.roundLabel||match.stage}</span></div><div className="score-sides"><b>{match.sideA}</b>{match.bestOf===3?<div className="set-inline">{sets.map((s,i)=><span key={i}><small>S{i+1}</small><input type="number" min="0" value={s.a} onChange={e=>setSets(v=>v.map((x,j)=>j===i?{...x,a:e.target.value}:x))}/><i>—</i><input type="number" min="0" value={s.b} onChange={e=>setSets(v=>v.map((x,j)=>j===i?{...x,b:e.target.value}:x))}/></span>)}</div>:<div className="score-pair"><input type="number" min="0" value={a} onChange={e=>setA(e.target.value)}/><i>—</i><input type="number" min="0" value={b} onChange={e=>setB(e.target.value)}/></div>}<b>{match.sideB}</b></div><button className={match.status==="finished"?"ghost small":"light small"} disabled={busy}>{match.status==="finished"?text(locale,"Corregir","Correct"):text(locale,"Guardar","Save")}</button></form>}

function TV({detail,locale,reload}:{detail:Detail;locale:Locale;reload:()=>Promise<void>}){
  const categories=detail.categories;
  const categoryIncomplete=(c:Category)=>Number(c.finishedGroupMatchCount)<Number(c.groupMatchCount)||detail.matches.some(m=>m.categoryId===c.id&&m.status!=="finished"&&m.status!=="bye"&&m.status!=="skipped");
  const incomplete=categories.find(categoryIncomplete)||categories[0];
  const [categoryId,setCategoryId]=useState(incomplete?.id||"");const [auto,setAuto]=useState(true);
  useEffect(()=>{if(!auto)return;const timer=window.setInterval(()=>void reload(),5000);return()=>window.clearInterval(timer)},[auto,reload]);
  useEffect(()=>{if(!auto)return;const selected=categories.find(c=>c.id===categoryId);if(!selected||!categoryIncomplete(selected)){const next=categories.find(categoryIncomplete)||categories[categories.length-1];if(next&&next.id!==categoryId)setCategoryId(next.id);}},[auto,categoryId,categories,detail.matches]);
  const category=categories.find(c=>c.id===categoryId)||incomplete;
  if(category?.entryType==="team")return <section className="tpw-stack"><article className="panel tv-team-selector"><div className="form-actions"><select value={category.id} onChange={e=>{setCategoryId(e.target.value);setAuto(false)}}>{categories.map(c=><option key={c.id} value={c.id}>{c.entryType==="team"?"TEAM · ":""}{c.name}</option>)}</select><button onClick={()=>setAuto(v=>!v)}>{auto?"AUTO ON":"AUTO OFF"}</button><button onClick={()=>void document.documentElement.requestFullscreen?.()}>⛶</button></div></article><TeamTVPanel tournamentId={detail.tournament.id} categoryId={category.id} locale={locale} tournamentName={detail.tournament.name}/></section>;
  const upcoming=detail.schedule.filter(s=>s.categoryId===category?.id&&s.matchId&&detail.matches.find(m=>m.matchId===s.matchId)?.status!=="finished").slice(0,5);
  const recent=detail.matches.filter(m=>m.categoryId===category?.id&&m.status==="finished").sort((a,b)=>Number(b.scheduleStart??0)-Number(a.scheduleStart??0)).slice(0,5);
  const finals=detail.matches.filter(m=>m.categoryId===category?.id&&m.stage!=="group");
  const groupsComplete=category?Number(category.groupMatchCount)>0&&Number(category.finishedGroupMatchCount)>=Number(category.groupMatchCount):false;
  return <section className="tv-shell"><header><div><span>HUAU TOURNAMENT</span><h2>{detail.tournament.name}</h2></div><div className="form-actions"><select value={category?.id||""} onChange={e=>{setCategoryId(e.target.value);setAuto(false)}}>{categories.map(c=><option key={c.id} value={c.id}>{c.entryType==="team"?"TEAM · ":""}{c.name}</option>)}</select><button onClick={()=>setAuto(v=>!v)}>{auto?"AUTO ON":"AUTO OFF"}</button><button onClick={()=>void document.documentElement.requestFullscreen?.()}>⛶</button></div></header><div className="tv-category"><div><span>{groupsComplete&&finals.length?text(locale,"FASE FINAL","FINAL PHASE"):category?.competitionStatus||""}</span><h1>{category?.name||"—"}</h1></div><strong>{new Date().toLocaleTimeString("es-UY",{hour:"2-digit",minute:"2-digit"})}</strong></div><div className="tv-grid"><div className="tv-main">{groupsComplete&&finals.length?<div className="bracket tv-bracket"><h3>{text(locale,"Fase final","Final phase")}</h3>{finals.map(m=><div className="bracket-row" key={m.encounterId}><span>{m.roundLabel||m.stage}</span><strong>{m.sideA||"TBD"} <em>vs</em> {m.sideB||"TBD"}</strong><small>{m.status}</small></div>)}</div>:<div className="competition-groups">{grouped(detail,category?.id||"").map(g=><StandingsCard key={g.id} detail={detail} categoryId={category?.id||""} groupId={g.id} groupName={g.name} entries={g.entries} locale={locale}/>)}</div>}</div><aside><h3>{text(locale,"Próximos partidos","Upcoming matches")}</h3>{upcoming.map(s=><div className="tv-match" key={s.id}><b>{time(s.startAt)} · {s.courtLabel}</b><span>{s.sideA} — {s.sideB}</span></div>)}<h3>{text(locale,"Últimos resultados","Latest results")}</h3>{recent.map(m=><div className="tv-match" key={m.encounterId}><b>{m.scoreA} — {m.scoreB}</b><span>{m.sideA} / {m.sideB}</span></div>)}</aside></div></section>
}
function SettingsPanel({detail,locale,organizationId,busy,act,go}:{detail:Detail;locale:Locale;organizationId:string;busy:boolean;act:ActionRunner;go:(p:string)=>void}){
  const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const close=String(f.get("registrationClose")||"");await act(()=>request(`/api/admin/tournaments/${detail.tournament.id}/settings`,{method:"PUT",body:JSON.stringify({club:f.get("club"),city:f.get("city"),location:f.get("location"),description:f.get("description"),contact:f.get("contact"),startDate:f.get("startDate"),endDate:f.get("endDate")||null,dailyStart:f.get("dailyStart"),dailyEnd:f.get("dailyEnd"),courtCount:Number(f.get("courtCount")),defaultMatchMinutes:Number(f.get("defaultMatchMinutes")),paymentType:f.get("paymentType"),entryFeeMinor:moneyMinor(f.get("entryFee")),baseFeeMinor:moneyMinor(f.get("baseFee")),extraCategoryFeeMinor:moneyMinor(f.get("extraCategoryFee")),registrationCloseAt:close?Math.floor(new Date(close).getTime()/1000):null,minimumGroup:Number(f.get("minimumGroup")),preferredGroup:Number(f.get("preferredGroup")),maximumGroup:Number(f.get("maximumGroup")),suggestedQualifiersPerGroup:Number(f.get("suggestedQualifiersPerGroup")),seedingMethod:f.get("seedingMethod"),minimumRestSlots:Number(f.get("minimumRestSlots"))})}));};
  const backup=async()=>{const data=await request(`/api/admin/tournaments/${detail.tournament.id}/backup`);downloadJson(`${detail.tournament.slug}-backup.json`,data);};
  const importFile=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());const result=await request<{tournament:{id:string}}>(`/api/admin/organizations/${organizationId}/tournaments/import`,{method:"POST",body:JSON.stringify(data)});go(`/admin/organizations/${organizationId}/tournaments/${result.tournament.id}`);}catch(error){window.alert(error instanceof Error?error.message:"Import error");}};
  const reset=()=>{if(!window.confirm(text(locale,"¿Eliminar formatos activos, grupos, resultados y cronograma? Se conservarán jugadores, categorías y datos del torneo. HUAU guardará snapshots antes.","Remove active formats, groups, results and schedule? Players, categories and tournament data will remain. HUAU will snapshot first.")))return;void act(()=>request(`/api/admin/tournaments/${detail.tournament.id}/reset-competition`,{method:"POST",body:JSON.stringify({confirm:true})}));};
  const removeTournament=()=>{const typed=window.prompt(text(locale,`Esta acción elimina TODO el torneo y no se puede deshacer. Escribí exactamente: ${detail.tournament.name}`,`This deletes the ENTIRE tournament and cannot be undone. Type exactly: ${detail.tournament.name}`));if(typed!==detail.tournament.name)return;void act(async()=>{await request(`/api/admin/tournaments/${detail.tournament.id}`,{method:"DELETE",body:JSON.stringify({confirmDelete:true})});go(`/admin/organizations/${organizationId}/tournaments`);},undefined,"none");};
  return <section className="tpw-stack"><article className="panel"><div className="panel-title"><div><div className="eyebrow">{text(locale,"CONFIGURACIÓN LEGACY","LEGACY SETTINGS")}</div><h2>{text(locale,"Datos del torneo y planificación","Tournament data & planning")}</h2></div></div><form className="tpw-form" onSubmit={save}><div className="three"><Field n="club" l="Club" value={detail.settings.club}/><Field n="city" l={text(locale,"Ciudad","City")} value={detail.settings.city}/><Field n="location" l={text(locale,"Lugar / dirección","Venue / address")} value={detail.settings.location}/></div><div className="three"><Field n="contact" l={text(locale,"Contacto organizador","Organizer contact")} value={detail.settings.contact}/><Field n="startDate" l={text(locale,"Inicio","Start")} type="date" value={iso(detail.tournament.startAt)} required/><Field n="endDate" l={text(locale,"Fin","End")} type="date" value={detail.tournament.endAt?iso(detail.tournament.endAt):""}/></div><label><span>{text(locale,"Descripción","Description")}</span><textarea name="description" rows={3} defaultValue={detail.settings.description}/></label><div className="four"><Field n="dailyStart" l={text(locale,"Inicio jornada","Day start")} type="time" value={detail.settings.dailyStart}/><Field n="dailyEnd" l={text(locale,"Fin objetivo","Target end")} type="time" value={detail.settings.dailyEnd}/><Field n="courtCount" l={text(locale,"Canchas","Courts")} type="number" value={String(detail.tournament.courtCount)} required/><Field n="defaultMatchMinutes" l={text(locale,"Min/partido default","Default min/match")} type="number" value={String(detail.settings.defaultMatchMinutes)}/></div><div className="four"><Field n="minimumGroup" l={text(locale,"Grupo mínimo","Min group")} type="number" value={String(detail.settings.minimumGroup)}/><Field n="preferredGroup" l={text(locale,"Grupo preferido","Preferred group")} type="number" value={String(detail.settings.preferredGroup)}/><Field n="maximumGroup" l={text(locale,"Grupo máximo","Max group")} type="number" value={String(detail.settings.maximumGroup)}/><Select n="suggestedQualifiersPerGroup" l={text(locale,"Clasificados sugeridos","Suggested qualifiers")} value={String(detail.settings.suggestedQualifiersPerGroup)} options={[["0","Auto"],["1","1"],["2","2"]]}/></div><div className="four"><Select n="seedingMethod" l={text(locale,"Siembra default","Default seeding")} value={detail.settings.seedingMethod} options={[["snake",text(locale,"DUPR serpentina","DUPR snake")],["random",text(locale,"Aleatorio","Random")],["manual",text(locale,"Manual","Manual")],["live",text(locale,"Sorteo en vivo","Live draw")]]}/><Select n="minimumRestSlots" l={text(locale,"Descanso mínimo","Minimum rest")} value={String(detail.settings.minimumRestSlots)} options={[["0","0"],["1","1"],["2","2"]]}/><Select n="paymentType" l={text(locale,"Tipo de pago","Payment type")} value={detail.settings.paymentType} options={[["per_category",text(locale,"Pago por categoría","Per category")],["base_plus_extra",text(locale,"Base + categoría extra","Base + extra category")],["free",text(locale,"Gratuito","Free")]]}/><Field n="registrationClose" l={text(locale,"Cierre de inscripciones","Registration close")} type="datetime-local" value={dateTimeLocal(detail.settings.registrationCloseAt)}/></div><div className="three"><Field n="entryFee" l={text(locale,"Precio/categoría","Fee/category")} type="number" step="0.01" value={minorMoney(detail.settings.entryFeeMinor)}/><Field n="baseFee" l={text(locale,"Precio base","Base fee")} type="number" step="0.01" value={minorMoney(detail.settings.baseFeeMinor)}/><Field n="extraCategoryFee" l={text(locale,"Categoría extra","Extra category")} type="number" step="0.01" value={minorMoney(detail.settings.extraCategoryFeeMinor)}/></div><button className="light" disabled={busy}>{text(locale,"Guardar configuración","Save settings")}</button></form></article><article className="panel"><h2>{text(locale,"Backup, importación e imágenes","Backup, import & images")}</h2><p>{text(locale,"Exporta el estado operativo y permite importar un backup/V2.4.2 como una copia nueva, sin pisar silenciosamente el torneo activo.","Exports operational state and imports backup/V2.4.2 as a new copy without silently overwriting the active tournament.")}</p><div className="asset-actions"><button className="ghost" onClick={()=>void backup()}>{text(locale,"Exportar backup JSON","Export JSON backup")}</button><label className="light file-button">{text(locale,"Importar backup / V2.4.2","Import backup / V2.4.2")}<input type="file" accept="application/json,.json" onChange={e=>void importFile(e)}/></label><button className="ghost" onClick={()=>downloadGroupImages(detail,locale)}>{text(locale,"Imágenes de grupos","Groups images")}</button><button className="ghost" onClick={()=>downloadPromoImage(detail,locale)}>{text(locale,"Placa del torneo","Tournament promo")}</button></div></article><PublishControls detail={detail} locale={locale} busy={busy} act={act}/><article className="panel danger-zone"><div><div className="eyebrow">{text(locale,"ZONA DE RIESGO","DANGER ZONE")}</div><h2>{text(locale,"Reiniciar competencia","Reset competition")}</h2><p>{text(locale,"Elimina formatos activos, grupos, resultados y cronograma; conserva jugadores, categorías y datos del torneo. La nueva HUAU crea snapshots antes de hacerlo.","Removes active formats, groups, results and schedule; keeps players, categories and tournament data. New HUAU snapshots first.")}</p></div><div className="danger-actions"><button className="danger" disabled={busy} onClick={reset}>{text(locale,"Reiniciar competencia","Reset competition")}</button><button className="danger destructive" disabled={busy} onClick={removeTournament}>{text(locale,"Eliminar torneo completo","Delete entire tournament")}</button></div></article></section>
}

function PublishControls({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){const update=(payload:Record<string,unknown>)=>act(()=>request(`/api/admin/tournaments/${detail.tournament.id}`,{method:"PUT",body:JSON.stringify(payload)}));return <article className="panel"><h2>{text(locale,"Estado y visibilidad","Status & visibility")}</h2><div className="status-actions">{["draft","registration_open","registration_closed","draw_ready","scheduled","live","completed"].map(s=><button key={s} className={detail.tournament.status===s?"light small":"ghost small"} disabled={busy} onClick={()=>void update({status:s})}>{s.replaceAll("_"," ")}</button>)}</div><div className="toggle-row"><span>{text(locale,"Participantes públicos","Public participants")}</span><button className={detail.tournament.publicParticipants?"light small":"ghost small"} onClick={()=>void update({publicParticipants:!detail.tournament.publicParticipants})}>{detail.tournament.publicParticipants?"ON":"OFF"}</button></div><div className="toggle-row"><span>Live</span><button className={detail.tournament.publicLive?"light small":"ghost small"} onClick={()=>void update({publicLive:!detail.tournament.publicLive})}>{detail.tournament.publicLive?"ON":"OFF"}</button></div></article>}

function Recovery({detail,locale,busy,act}:{detail:Detail;locale:Locale;busy:boolean;act:ActionRunner}){return <section className="panel"><div className="panel-title"><div><h2>{text(locale,"Snapshots y recuperación","Snapshots & recovery")}</h2><p>{text(locale,"Cambios estructurales críticos guardan el estado anterior antes de modificarlo.","Critical structural changes save the previous state first.")}</p></div><span>{detail.snapshots.length}</span></div><div className="snapshot-list">{detail.snapshots.map(s=><article key={s.id}><div><strong>{s.categoryName||text(locale,"Torneo","Tournament")}</strong><span>{s.reason}</span><small>{dt(s.createdAt)} · rev. {s.revision}</small></div>{s.scopeType==="category"&&<button className="ghost small" disabled={busy} onClick={()=>{if(window.confirm(text(locale,"¿Restaurar este snapshot? Se guardará primero el estado actual.","Restore this snapshot? The current state will be saved first.")))void act(()=>request(`/api/admin/tournament-snapshots/${s.id}/restore`,{method:"POST",body:"{}"}));}}>{text(locale,"Restaurar","Restore")}</button>}</article>)}</div></section>}

function Field({n,l,type="text",value="",required=false,step}:{n:string;l:string;type?:string;value?:string;required?:boolean;step?:string}){return <label><span>{l}</span><input name={n} type={type} defaultValue={value} required={required} step={step} min={type==="number"?"0":undefined}/></label>}
function Select({n,l,options,value}:{n:string;l:string;options:Array<[string,string]>;value?:string}){return <label><span>{l}</span><select name={n} defaultValue={value??options[0]?.[0]}>{options.map(([v,label])=><option value={v} key={v}>{label}</option>)}</select></label>}
function moneyMinor(v:FormDataEntryValue|null){const n=Number(v);return Number.isFinite(n)&&n>0?Math.round(n*100):null}function minorMoney(v:number|null){return v===null?"":String(v/100)}
function downloadJson(name:string,data:unknown){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
function canvasDownload(name:string,width:number,height:number,draw:(ctx:CanvasRenderingContext2D)=>void){const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const ctx=canvas.getContext("2d");if(!ctx)return;draw(ctx);canvas.toBlob(blob=>{if(!blob)return;const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)},"image/png")}
function wrap(ctx:CanvasRenderingContext2D,value:string,max:number){const words=value.split(" ");const lines:string[]=[];let line="";for(const w of words){const test=line?`${line} ${w}`:w;if(ctx.measureText(test).width>max&&line){lines.push(line);line=w}else line=test}if(line)lines.push(line);return lines}
function imageBase(ctx:CanvasRenderingContext2D,title:string,subtitle:string){ctx.fillStyle="#090909";ctx.fillRect(0,0,1080,1920);ctx.fillStyle="#fff";ctx.font="700 64px Arial";ctx.fillText("HUAU",70,110);ctx.font="700 48px Arial";wrap(ctx,title,900).slice(0,2).forEach((line,i)=>ctx.fillText(line,70,230+i*58));ctx.fillStyle="#aaa";ctx.font="28px Arial";ctx.fillText(subtitle,70,360)}
function downloadScheduleImages(detail:Detail,locale:Locale,categoryId?:string){
  const category=categoryId?detail.categories.find(c=>c.id===categoryId):null;const rows=detail.schedule.filter(r=>!categoryId||r.categoryId===categoryId);const chunks:ScheduleRow[][]=[];for(let i=0;i<rows.length;i+=18)chunks.push(rows.slice(i,i+18));chunks.forEach((pageRows,page)=>canvasDownload(`${detail.tournament.slug}-${category?slugAsset(category.name):"cronograma"}-${page+1}.png`,1080,1920,ctx=>{imageBase(ctx,category?.name||detail.tournament.name,text(locale,"CRONOGRAMA","SCHEDULE"));let y=440;pageRows.forEach(row=>{ctx.fillStyle="#777";ctx.font="24px Arial";ctx.fillText(`${dt(row.startAt)} · ${row.courtLabel}${category?"":` · ${row.categoryName}`}`,70,y);ctx.fillStyle="#fff";ctx.font="700 30px Arial";const title=row.sideA&&row.sideB?`${row.sideA} — ${row.sideB}`:text(locale,"Reserva de fase","Stage reservation");wrap(ctx,title,900).slice(0,2).forEach((line,i)=>ctx.fillText(line,70,y+42+i*34));ctx.fillStyle="#888";ctx.font="22px Arial";ctx.fillText(row.categoryEntryType==="team"?`TEAM · ${row.groupName?`${text(locale,"Grupo","Group")} ${row.groupName} · `:""}${row.roundLabel||row.rubberKey||"Rubber"}`:(row.groupName?`${text(locale,"Grupo","Group")} ${row.groupName}`:row.roundLabel||row.stage),70,y+106);y+=132});ctx.fillStyle="#777";ctx.font="22px Arial";ctx.fillText(`${page+1}/${chunks.length}`,940,1840)}));
}
function downloadGroupImages(detail:Detail,locale:Locale){
  detail.categories.forEach(category=>{const groups=grouped(detail,category.id);if(!groups.length)return;const pages:Array<typeof groups>=[];let current:typeof groups=[];let units=0;for(const group of groups){const need=2+group.entries.length;if(current.length&&units+need>24){pages.push(current);current=[];units=0}current.push(group);units+=need}if(current.length)pages.push(current);pages.forEach((pageGroups,page)=>canvasDownload(`${detail.tournament.slug}-${slugAsset(category.name)}-grupos-${page+1}.png`,1080,1920,ctx=>{imageBase(ctx,category.name,text(locale,"GRUPOS","GROUPS"));let y=440;pageGroups.forEach(group=>{ctx.fillStyle="#fff";ctx.font="700 34px Arial";ctx.fillText(`${text(locale,"Grupo","Group")} ${group.name}`,70,y);y+=48;ctx.font="28px Arial";group.entries.forEach(entry=>{ctx.fillStyle="#bbb";ctx.fillText(entry,90,y);y+=40});y+=34});ctx.fillStyle="#777";ctx.font="22px Arial";ctx.fillText(`${page+1}/${pages.length}`,940,1840)}))});
}
function downloadPromoImage(detail:Detail,locale:Locale){canvasDownload(`${detail.tournament.slug}-promo.png`,1080,1920,ctx=>{imageBase(ctx,detail.tournament.name,text(locale,"HUAU TOURNAMENT","HUAU TOURNAMENT"));let y=590;const line=(label:string,value:string)=>{ctx.fillStyle="#777";ctx.font="24px Arial";ctx.fillText(label.toUpperCase(),70,y);ctx.fillStyle="#fff";ctx.font="700 34px Arial";wrap(ctx,value||"—",900).slice(0,2).forEach((v,i)=>ctx.fillText(v,70,y+42+i*38));y+=118};line(text(locale,"Cuándo","When"),detail.tournament.endAt?`${date(detail.tournament.startAt)} — ${date(detail.tournament.endAt)}`:date(detail.tournament.startAt));line(text(locale,"Dónde","Where"),[detail.settings.city,detail.settings.location].filter(Boolean).join(" · "));line(text(locale,"Organiza","Organizer"),detail.settings.club||detail.tournament.name);line(text(locale,"Operación","Operation"),`${detail.tournament.courtCount} ${text(locale,"canchas","courts")} · ${detail.settings.dailyStart}–${detail.settings.dailyEnd}`);line(text(locale,"Categorías","Categories"),detail.categories.map(c=>c.name).join(" · "));const cost=detail.settings.paymentType==="free"?text(locale,"Gratuito","Free"):detail.settings.paymentType==="per_category"?(detail.settings.entryFeeMinor?`${minorMoney(detail.settings.entryFeeMinor)} UYU / ${text(locale,"categoría","category")}`:text(locale,"A definir","TBD")):`${detail.settings.baseFeeMinor?minorMoney(detail.settings.baseFeeMinor):"—"} UYU + ${detail.settings.extraCategoryFeeMinor?minorMoney(detail.settings.extraCategoryFeeMinor):"—"} UYU ${text(locale,"extra","extra")}`;line(text(locale,"Costo","Fee"),cost);if(detail.settings.registrationCloseAt)line(text(locale,"Cierre de inscripciones","Registration close"),dt(detail.settings.registrationCloseAt));line(text(locale,"Contacto","Contact"),detail.settings.contact);ctx.fillStyle="#fff";ctx.font="700 34px Arial";ctx.fillText("Powered by HUAU",70,1810)})}
function slugAsset(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}

